@st.cache_data
def carregar_dados(caminho, mtime):
    df = pd.read_parquet(caminho)
    df["din_instante"] = pd.to_datetime(df["din_instante"])
    return df


if not os.path.exists(CAMINHO_PARQUET):
    st.error(f"Arquivo não encontrado: {CAMINHO_PARQUET}")
    st.stop()

try:
    df = carregar_dados(
        CAMINHO_PARQUET,
        os.path.getmtime(CAMINHO_PARQUET),
    )
except Exception as e:
    st.error(f"Erro ao ler a base: {e}")
    st.stop()

if df.empty:
    st.warning("A base está vazia.")
    st.stop()

data_min = df["din_instante"].min().date()
data_max = df["din_instante"].max().date()

SUBSISTEMAS = sorted(df["nom_subsistema"].dropna().unique())

# ============================================================
# FUNÇÕES
# ============================================================

FONTES = {
    "Eólica": "val_gereolica",
    "Hidráulica": "val_gerhidraulica",
    "Térmica": "val_gertermica",
    "Solar": "val_gersolar",
}


def fim_do_dia(d):
    return pd.Timestamp(d) + pd.Timedelta(days=1) - pd.Timedelta(seconds=1)


def intervalo(d1, d2):
    return df[
        (df["din_instante"] >= pd.Timestamp(d1))
        & (df["din_instante"] <= fim_do_dia(d2))
    ].copy()



def formatar(valor, casas=0):
    if pd.isna(valor):
        return "—"
    return f"{valor:,.{casas}f} MW".replace(",", "X").replace(".", ",").replace("X", ".")


def valor_medio(base, coluna):
    if base.empty:
        return float("nan")
    return base[coluna].mean()


def preparar_serie_dia(base):
    if base.empty:
        return base

    serie = base.copy()
    serie["hora"] = serie["din_instante"].dt.hour

    return (
        serie.groupby(["nom_subsistema", "hora"], as_index=False)
        .agg(
            val_carga=("val_carga", "mean"),
            val_gerhidraulica=("val_gerhidraulica", "mean"),
            val_gertermica=("val_gertermica", "mean"),
            val_gereolica=("val_gereolica", "mean"),
            val_gersolar=("val_gersolar", "mean"),
            val_intercambio=("val_intercambio", "mean"),
        )
    )


def preparar_serie_periodo(base):
    return preparar_serie_dia(base)


def grafico_linha_carga_multiplos(series, fontes_label="Carga"):
    fig = go.Figure()

    for label, serie in series:
        subsistemas = serie["nom_subsistema"].unique()

        for subs in subsistemas:
            dados = serie[serie["nom_subsistema"] == subs]

            nome = (
                f"{label} — {subs}"
                if len(subsistemas) > 1
                else label
            )

            fig.add_trace(
                go.Scatter(
                    x=dados["hora"],
                    y=dados["val_carga"],
                    mode="lines+markers",
                    name=nome,
                    line=dict(width=3),
                    hovertemplate=(
                        f"{nome}<br>"
                        "%{x:02d}:00"
                        "<br>%{y:,.0f} MW"
                        "<extra></extra>"
                    ),
                )
            )

    fig.update_layout(
        height=380,
        margin=dict(l=20, r=20, t=20, b=20),
        plot_bgcolor="white",
        paper_bgcolor="white",
        xaxis=dict(
            title="Hora",
            tickmode="linear",
            dtick=2,
            ticksuffix="h",
            showgrid=True,
            gridcolor="#E5E5E5",
        ),
        yaxis=dict(
            title="MW",
            showgrid=True,
            gridcolor="#E5E5E5",
        ),
        hovermode="x unified",
        legend=dict(
            orientation="h",
            y=1.08,
            x=0,
        ),
    )
    return fig


def grafico_geracao_multiplos(series, fontes_exibir=None):
    fig = go.Figure()
    fontes_exibir = fontes_exibir or list(FONTES.keys())

    for label, serie in series:
        subsistemas = serie["nom_subsistema"].unique()

        for subs in subsistemas:
            dados = serie[serie["nom_subsistema"] == subs]

            for nome, coluna in FONTES.items():
                if nome not in fontes_exibir:
                    continue

                nome_serie = (
                    f"{nome} — {label} — {subs}"
                    if len(subsistemas) > 1
                    else f"{nome} — {label}"
                )

                fig.add_trace(
                    go.Scatter(
                        x=dados["hora"],
                        y=dados[coluna],
                        mode="lines",
                        name=nome_serie,
                        legendgroup=f"{nome}-{label}-{subs}",
                        line=dict(width=2),
                        hovertemplate=(
                            f"{nome_serie}<br>"
                            "%{x:02d}:00"
                            "<br>%{y:,.0f} MW"
                            "<extra></extra>"
                        ),
                    )
                )

    fig.update_layout(
        height=430,
        margin=dict(l=20, r=20, t=20, b=20),
        plot_bgcolor="white",
        paper_bgcolor="white",
        xaxis=dict(
            title="Hora",
            tickmode="linear",
            dtick=2,
            ticksuffix="h",
            showgrid=True,
            gridcolor="#E5E5E5",
        ),
        yaxis=dict(
            title="MW",
            showgrid=True,
            gridcolor="#E5E5E5",
        ),
        hovermode="x unified",
        legend=dict(
            orientation="h",
            y=-0.18,
            x=0,
        ),
    )
    return fig


def grafico_linha_carga(serie_a, label_a, serie_b=None, label_b=None):
    fig = go.Figure()

    subs_a = serie_a["nom_subsistema"].unique()

    for subs in subs_a:
        dados = serie_a[serie_a["nom_subsistema"] == subs]
        nome = subs if len(subs_a) > 1 else label_a

        fig.add_trace(
            go.Scatter(
                x=dados["hora"],
                y=dados["val_carga"],
                mode="lines+markers",
                name=nome,
                line=dict(width=3),
                hovertemplate=(
                    f"{subs}<br>%{{x:02d}}:00"
                    "<br>%{y:,.0f} MW<extra></extra>"
                ),
            )
        )

    if serie_b is not None:
        subs_b = serie_b["nom_subsistema"].unique()

        for subs in subs_b:
            dados = serie_b[serie_b["nom_subsistema"] == subs]
            nome = f"{subs} — {label_b}" if len(subs_b) > 1 else label_b

            fig.add_trace(
                go.Scatter(
                    x=dados["hora"],
                    y=dados["val_carga"],
                    mode="lines+markers",
                    name=nome,
                    line=dict(width=3, dash="dash"),
                    hovertemplate=(
                        f"{subs}<br>%{{x:02d}}:00"
                        "<br>%{y:,.0f} MW<extra></extra>"
                    ),
                )
            )

    fig.update_layout(
        height=380,
        margin=dict(l=20, r=20, t=20, b=20),
        plot_bgcolor="white",
        paper_bgcolor="white",
        xaxis=dict(
            title="Hora",
            tickmode="linear",
            dtick=2,
            ticksuffix="h",
            showgrid=True,
            gridcolor="#E5E5E5",
        ),
        yaxis=dict(
            title="MW",
            showgrid=True,
            gridcolor="#E5E5E5",
        ),
        hovermode="x unified",
        legend=dict(orientation="h", y=1.08, x=0),
    )
    return fig


def grafico_geracao(
    serie_a,
    label_a,
    serie_b=None,
    label_b=None,
    fontes_exibir=None,
):
    fig = go.Figure()
    fontes_exibir = fontes_exibir or list(FONTES.keys())

    subs_a = serie_a["nom_subsistema"].unique()

    for subs in subs_a:
        dados = serie_a[serie_a["nom_subsistema"] == subs]

        for nome, coluna in FONTES.items():
            if nome not in fontes_exibir:
                continue

            nome_serie = f"{nome} — {subs}" if len(subs_a) > 1 else nome

            fig.add_trace(
                go.Scatter(
                    x=dados["hora"],
                    y=dados[coluna],
                    mode="lines",
                    name=nome_serie,
                    legendgroup=f"{nome}-{subs}",
                    line=dict(width=2),
                    hovertemplate=(
                        f"{nome} | {subs}<br>%{{x:02d}}:00"
                        "<br>%{y:,.0f} MW<extra></extra>"
                    ),
                )
            )

    if serie_b is not None:
        subs_b = serie_b["nom_subsistema"].unique()

        for subs in subs_b:
            dados = serie_b[serie_b["nom_subsistema"] == subs]

            for nome, coluna in FONTES.items():
                if nome not in fontes_exibir:
                    continue

                nome_serie = (
                    f"{nome} — {subs} — {label_b}"
                    if len(subs_b) > 1
                    else f"{nome} — {label_b}"
                )

                fig.add_trace(
                    go.Scatter(
                        x=dados["hora"],
                        y=dados[coluna],
                        mode="lines",
                        name=nome_serie,
                        legendgroup=f"{nome}-{subs}-b",
                        line=dict(width=2, dash="dash"),
                        hovertemplate=(
                            f"{nome} | {subs} | {label_b}<br>%{{x:02d}}:00"
                            "<br>%{y:,.0f} MW<extra></extra>"
                        ),
                    )
                )

    fig.update_layout(
        height=430,
        margin=dict(l=20, r=20, t=20, b=20),
        plot_bgcolor="white",
        paper_bgcolor="white",
        xaxis=dict(
            title="Hora",
            tickmode="linear",
            dtick=2,
            ticksuffix="h",
            showgrid=True,
            gridcolor="#E5E5E5",
        ),
        yaxis=dict(
            title="MW",
            showgrid=True,
            gridcolor="#E5E5E5",
        ),
        hovermode="x unified",
        legend=dict(orientation="h", y=-0.18, x=0),
    )
    return fig


def grafico_pizza_geracao(linha, titulo, fontes_exibir=None):
    valores = []
    nomes = []

    fontes_exibir = fontes_exibir or list(FONTES.keys())

    for nome, coluna in FONTES.items():
        if nome not in fontes_exibir:
            continue
        valor = linha[coluna]
        if pd.notna(valor) and valor > 0:
            nomes.append(nome)
            valores.append(valor)

    fig = go.Figure(
        go.Pie(
            labels=nomes,
            values=valores,
            hole=0.48,
            textinfo="percent",
            hovertemplate="%{label}<br>%{value:,.0f} MW<extra></extra>",
        )
    )

    fig.update_layout(
        title=titulo,
        height=360,
        margin=dict(l=10, r=10, t=50, b=10),
        paper_bgcolor="white",
        showlegend=True,
        legend=dict(orientation="v"),
    )
    return fig


def grafico_pizza_carga(linha, titulo):
    valor = linha["val_carga"]

    fig = go.Figure(
        go.Pie(
            labels=["Carga"],
            values=[valor],
            hole=0.48,
            textinfo="percent",
            hovertemplate="Carga<br>%{value:,.0f} MW<extra></extra>",
        )
    )

    fig.update_layout(
        title=titulo,
        height=360,
        margin=dict(l=10, r=10, t=50, b=10),
        paper_bgcolor="white",
        showlegend=True,
    )
    return fig



