st.markdown("---")

# A composição agora representa a média do dia/período, e não um horário
# escolhido manualmente. Isso deixa a tela mais limpa e mantém a comparação
# consistente.

def linha_media(base):
    linha = {}
    for coluna in FONTES.values():
        linha[coluna] = base[coluna].mean()
    linha["val_carga"] = base["val_carga"].mean()
    linha["val_intercambio"] = base["val_intercambio"].mean()
    return pd.Series(linha)

if modo == "DIA" and len(bases_dia) > 1:

    st.markdown("#### Composição média da geração por dia")

    linhas_composicao = []

    for dia, base in bases_dia:
        linha = {
            "Dia": dia.strftime("%d/%m/%Y"),
        }

        for nome, coluna in FONTES.items():
            if nome in fontes_selecionadas:
                linha[nome] = base[coluna].mean()

        linhas_composicao.append(linha)

    tabela_composicao = pd.DataFrame(linhas_composicao)

    st.dataframe(
        tabela_composicao.style.format(
            {
                fonte: "{:,.0f} MW"
                for fonte in fontes_selecionadas
            }
        ),
        use_container_width=True,
        hide_index=True,
    )

else:

    def linha_media(base):
        linha = {}
        for coluna in FONTES.values():
            linha[coluna] = base[coluna].mean()
        linha["val_carga"] = base["val_carga"].mean()
        linha["val_intercambio"] = base["val_intercambio"].mean()
        return pd.Series(linha)

    media_a = linha_media(base_a)

    p1, p2 = st.columns(2)

    with p1:
        st.plotly_chart(
            grafico_pizza_geracao(
                media_a,
                f"Composição média da geração — {label_a}",
                fontes_selecionadas,
            ),
            use_container_width=True,
        )

    with p2:
        if base_b is not None and not base_b.empty:
            media_b = linha_media(base_b)

            fig_carga_comp = go.Figure(
                data=[
                    go.Bar(
                        x=[label_a, label_b],
                        y=[
                            media_a["val_carga"],
                            media_b["val_carga"],
                        ],
                        text=[
                            f"{media_a['val_carga']:,.0f} MW",
                            f"{media_b['val_carga']:,.0f} MW",
                        ],
                        textposition="outside",
                        hovertemplate=(
                            "%{x}<br>%{y:,.0f} MW"
                            "<extra></extra>"
                        ),
                    )
                ]
            )

            fig_carga_comp.update_layout(
                title="Carga média — comparação",
                height=360,
                margin=dict(l=10, r=10, t=50, b=10),
                paper_bgcolor="white",
                plot_bgcolor="white",
                yaxis_title="MW",
                xaxis_title="",
            )

            st.plotly_chart(
                fig_carga_comp,
                use_container_width=True,
            )

        else:
            fig_carga_media = go.Figure(
                data=[
                    go.Bar(
                        x=[label_a],
                        y=[media_a["val_carga"]],
                        text=[
                            f"{media_a['val_carga']:,.0f} MW"
                        ],
                        textposition="outside",
                        hovertemplate=(
                            "Carga média<br>"
                            "%{y:,.0f} MW"
                            "<extra></extra>"
                        ),
                    )
                ]
            )

            fig_carga_media.update_layout(
                title="Carga média do dia",
                height=360,
                margin=dict(l=10, r=10, t=50, b=10),
                paper_bgcolor="white",
                plot_bgcolor="white",
                yaxis_title="MW",
                xaxis_title="",
            )

            st.plotly_chart(
                fig_carga_media,
                use_container_width=True,
            )

